def lookup_s7_module(mlfb_prefix: str) -> str:
    """
    Look up Siemens S7 module description from MLFB order number prefix.

    Args:
        mlfb_prefix: The first 7 characters of an MLFB order number (e.g., "6ES7315")

    Returns:
        Module description or "Unknown Module" if not found
    """
    # Try exact match first
    if mlfb_prefix in siemens_s7_modules:
        return siemens_s7_modules[mlfb_prefix]

    # Try with first 7 chars
    prefix_7 = mlfb_prefix[:7] if len(mlfb_prefix) >= 7 else mlfb_prefix
    if prefix_7 in siemens_s7_modules:
        return siemens_s7_modules[prefix_7]

    return "Unknown Module"


def lookup_s7_series(module_type_name: str) -> str:
    """
    Look up Siemens S7 series from module type name.

    Args:
        module_type_name: The module type name returned by snap7 (e.g., "CPU 315-2 DP")

    Returns:
        S7 series (e.g., "S7-300") or "Unknown Series" if not found
    """
    # Try longest match first (more specific)
    for prefix in sorted(siemens_s7_series.keys(), key=len, reverse=True):
        if module_type_name.startswith(prefix):
            return siemens_s7_series[prefix]

    return "Unknown Series"
